toolScript:
let chartInstance = null;
        let legs = [];
        function addLeg(data = null) {
            const leg = data || { action: 'buy', type: 'call', strike: 100, premium: 5, id: Date.now() };
            legs.push(leg);
            renderLegs();
            updateChart();
        }
        function removeLeg(id) {
            legs = legs.filter(l => l.id !== id);
            renderLegs();
            updateChart();
        }
        function clearAll() {
            if (!confirm("Purge current build?")) return;
            legs = [];
            renderLegs();
            updateChart();
        }
        function updateLeg(id, field, value) {
            const leg = legs.find(l => l.id === id);
            if (leg) {
                if (field === 'strike' || field === 'premium') leg[field] = parseFloat(value) || 0;
                else leg[field] = value;
                updateChart();
                if (field === 'action') renderLegs();
            }
        }
        function renderLegs() {
            const container = document.getElementById('legs-container');
            container.innerHTML = '';
            legs.forEach(leg => {
                const div = document.createElement('div');
                div.className = `leg-row ${leg.action}`;
                div.innerHTML = `
                    <select class="trade-input" onchange="updateLeg(${leg.id}, 'action', this.value)">
                        <option value="buy" ${leg.action === 'buy' ? 'selected' : ''}>Buy</option>
                        <option value="sell" ${leg.action === 'sell' ? 'selected' : ''}>Sell</option>
                    </select>
                    <select class="trade-input" onchange="updateLeg(${leg.id}, 'type', this.value)">
                        <option value="call" ${leg.type === 'call' ? 'selected' : ''}>Call</option>
                        <option value="put" ${leg.type === 'put' ? 'selected' : ''}>Put</option>
                    </select>
                    <input type="number" class="trade-input" value="${leg.strike}" placeholder="Strike" oninput="updateLeg(${leg.id}, 'strike', this.value)">
                    <input type="number" class="trade-input" value="${leg.premium}" placeholder="Price" oninput="updateLeg(${leg.id}, 'premium', this.value)">
                    <button onclick="removeLeg(${leg.id})" class="text-slate-500 hover:text-red-500 font-bold text-xl">&times;</button>
                `;
                container.appendChild(div);
            });
        }
        function loadPreset(type) {
            const spot = parseFloat(document.getElementById('spot-price').value) || 100;
            legs = [];
            if (type === 'straddle') {
                addLeg({ action: 'buy', type: 'call', strike: spot, premium: 5, id: 1 });
                addLeg({ action: 'buy', type: 'put', strike: spot, premium: 5, id: 2 });
            } else if (type === 'strangle') {
                addLeg({ action: 'buy', type: 'call', strike: spot + 10, premium: 3, id: 1 });
                addLeg({ action: 'buy', type: 'put', strike: spot - 10, premium: 3, id: 2 });
            } else if (type === 'bull_spread') {
                addLeg({ action: 'buy', type: 'call', strike: spot, premium: 5, id: 1 });
                addLeg({ action: 'sell', type: 'call', strike: spot + 10, premium: 2, id: 2 });
            } else if (type === 'iron_condor') {
                addLeg({ action: 'sell', type: 'put', strike: spot - 10, premium: 3, id: 1 });
                addLeg({ action: 'buy', type: 'put', strike: spot - 20, premium: 1, id: 2 });
                addLeg({ action: 'sell', type: 'call', strike: spot + 10, premium: 3, id: 3 });
                addLeg({ action: 'buy', type: 'call', strike: spot + 20, premium: 1, id: 4 });
            } else if (type === 'butterfly') {
                addLeg({ action: 'buy', type: 'call', strike: spot - 10, premium: 4, id: 1 });
                addLeg({ action: 'sell', type: 'call', strike: spot, premium: 1.5, id: 2 });
                addLeg({ action: 'sell', type: 'call', strike: spot, premium: 1.5, id: 3 });
                addLeg({ action: 'buy', type: 'call', strike: spot + 10, premium: 0.5, id: 4 });
            } else if (type === 'protective_put') {
                addLeg({ action: 'buy', type: 'put', strike: spot - 5, premium: 2, id: 1 });
            }
        }
        function calculatePL(price) {
            let totalPL = 0;
            legs.forEach(leg => {
                let val = 0;
                if (leg.type === 'call') val = Math.max(0, price - leg.strike);
                else val = Math.max(0, leg.strike - price);
                if (leg.action === 'buy') totalPL += (val - leg.premium);
                else totalPL += (leg.premium - val);
            });
            return totalPL * 100; // Multiplier 100
        }
        function updateChart() {
            const spot = parseFloat(document.getElementById('spot-price').value) || 100;
            const range = spot * 0.5;
            const minPrice = Math.max(0, spot - range);
            const maxPrice = spot + range;
            const steps = 60;
            const stepSize = (maxPrice - minPrice) / steps;
            const labels = [];
            const data = [];
            let maxP = -Infinity;
            let minP = Infinity;
            let breakevens = [];
            for (let i = 0; i <= steps; i++) {
                const price = minPrice + (i * stepSize);
                const pl = calculatePL(price);
                labels.push(price.toFixed(1));
                data.push(pl);
                if (pl > maxP) maxP = pl;
                if (pl < minP) minP = pl;
                if (i > 0) {
                    const prevPL = data[i - 1];
                    if ((prevPL < 0 && pl >= 0) || (prevPL > 0 && pl <= 0)) {
                        breakevens.push(price.toFixed(2));
                    }
                }
            }
            document.getElementById('res-max-profit').innerText = maxP > 100000 ? '∞' : '$' + Math.round(maxP).toLocaleString();
            document.getElementById('res-max-loss').innerText = minP < -100000 ? '∞' : '$' + Math.round(minP).toLocaleString();
            document.getElementById('res-breakeven').innerText = breakevens.length ? breakevens.join(' | ') : 'N/A';
            const ctx = document.getElementById('payoffChart').getContext('2d');
            if (chartInstance) chartInstance.destroy();
            chartInstance = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'P/L',
                        data: data,
                        borderColor: '#3b82f6',
                        borderWidth: 3,
                        pointRadius: 0,
                        fill: { target: 'origin', above: 'rgba(34, 197, 94, 0.1)', below: 'rgba(239, 68, 68, 0.1)' },
                        segment: { borderColor: ctx => ctx.p0.parsed.y >= 0 ? '#22c55e' : '#ef4444' }
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    scales: {
                        x: { grid: { color: '#334155' }, ticks: { color: '#94a3b8', font: { family: 'JetBrains Mono' } } },
                        y: { grid: { color: '#334155' }, ticks: { color: '#94a3b8', font: { family: 'JetBrains Mono' } } }
                    }
                }
            });
        }
        document.addEventListener('DOMContentLoaded', () => loadPreset('bull_spread'));
